PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "Restaurant" (
	"rtr_id"	INTEGER NOT NULL UNIQUE,
	"name"	TEXT NOT NULL,
	"description"	TEXT,
	"phone"	TEXT NOT NULL UNIQUE,
	"email"	TEXT NOT NULL UNIQUE,
	"password_HS"	TEXT NOT NULL,
	"address"	TEXT NOT NULL,
	"city"	TEXT NOT NULL,
	"state"	TEXT NOT NULL,
	"zip"	INTEGER NOT NULL,
	"hours"	TEXT,
	"status"	TEXT,
	PRIMARY KEY("rtr_id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "Order" (
	"ord_id"	INTEGER NOT NULL UNIQUE,
	"rtr_id"	INTEGER NOT NULL,
	"usr_id"	INTEGER NOT NULL,
	"details"	TEXT NOT NULL,
	"status"	INTEGER NOT NULL,
	PRIMARY KEY("ord_id" AUTOINCREMENT),
	FOREIGN KEY("rtr_id") REFERENCES "Restaurant"("rtr_id"),
	FOREIGN KEY("usr_id") REFERENCES "User"("usr_id")
);
CREATE TABLE IF NOT EXISTS "Review" (
	"rev_id"	INTEGER NOT NULL UNIQUE,
	"rtr_id"	INTEGER NOT NULL,
	"usr_id"	INTEGER NOT NULL,
	"title"	TEXT,
	"rating"	INTEGER NOT NULL,
	"description"	TEXT,
	PRIMARY KEY("rev_id" AUTOINCREMENT),
	FOREIGN KEY("rtr_id") REFERENCES "Restaurant"("rtr_id"),
	FOREIGN KEY("usr_id") REFERENCES "User"("usr_id")
);
CREATE TABLE IF NOT EXISTS "User" (
	"usr_id"	INTEGER NOT NULL UNIQUE,
	"first_name"	TEXT NOT NULL,
	"last_name"	TEXT NOT NULL,
	"email"	TEXT NOT NULL UNIQUE,
	"phone"	TEXT NOT NULL UNIQUE,
	"password_HS"	TEXT NOT NULL,
	"wallet"	INTEGER NOT NULL,
	"preferences"	TEXT,
	"allergies"	TEXT,
	"generated_menu"	TEXT, is_admin INTEGER DEFAULT 0,
	PRIMARY KEY("usr_id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "MenuItem" (
	"itm_id"	INTEGER NOT NULL UNIQUE,
	"rtr_id"	INTEGER NOT NULL,
	"name"	TEXT NOT NULL,
	"description"	TEXT,
	"price"	INTEGER NOT NULL,
	"calories"	INTEGER NOT NULL,
	"instock"	INTEGER NOT NULL,
	"restock"	TEXT,
	"allergens"	TEXT,
	PRIMARY KEY("itm_id" AUTOINCREMENT),
	FOREIGN KEY("rtr_id") REFERENCES "Restaurant"
);
CREATE TABLE Ticket (
            ticket_id INTEGER PRIMARY KEY AUTOINCREMENT,
            usr_id INTEGER NOT NULL,
            ord_id INTEGER NOT NULL,
            message TEXT NOT NULL,
            response TEXT,
            status TEXT NOT NULL DEFAULT 'Open',
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (usr_id) REFERENCES User(usr_id),
            FOREIGN KEY (ord_id) REFERENCES "Order"(ord_id)
        );
CREATE TRIGGER update_ticket_timestamp 
        AFTER UPDATE ON Ticket
        FOR EACH ROW
        BEGIN
            UPDATE Ticket SET updated_at = CURRENT_TIMESTAMP
            WHERE ticket_id = NEW.ticket_id;
        END;
CREATE INDEX idx_ticket_usr_id 
        ON Ticket(usr_id)
    ;
CREATE INDEX idx_ticket_status 
        ON Ticket(status)
    ;
CREATE INDEX idx_ticket_created_at 
        ON Ticket(created_at DESC)
    ;
COMMIT;
