INSERT INTO Review VALUES(1,17,24,'Amazing Pizza!',5,'Best pizza I''m Raleigh. Crust was perfectly crispy, toppings were fresh. Will be back!');
INSERT INTO Review VALUES(2,17,30,'Mediocre Burger',3,'Burger was okay, nothing special. Fries were soggy. Service was slow.');
INSERT INTO Review VALUES(3,14,24,'Delicious Sushi',4,'Fresh sushi, great selection, reasonable prices. Highly recommend.');
INSERT INTO Review VALUES(4,17,21,'Terrible Service',1,'The worst service I’m ever experienced. Rude staff, long wait times, and inaccurate order.');
INSERT INTO Review VALUES(5,12,30,'Great Brunch Spot',5,'Fantastic brunch! Eggs were cooked perfectly, and the atmosphere was lively.');
INSERT INTO Review VALUES(6,10,67,'Overpriced and Bland',2,'Food was bland and overpriced.  Not worth the money.');
INSERT INTO Review VALUES(7,9,96,'Authentic Mexican Food',4,'Really tasty and authentic Mexican food.  The salsa is fantastic.');
INSERT INTO Review VALUES(8,11,14,'Clean and Friendly',3,'Clean and friendly environment. The food was average but nothing to complain about.');
INSERT INTO Review VALUES(9,3,69,'Romantic Dinner',5,'Perfect for a romantic dinner. Great food, wine list, and ambiance.');
INSERT INTO Review VALUES(10,8,100,'Long Wait Times',2,'Had to wait an hour for a table. Food was okay, but not worth the wait.');
INSERT INTO Review VALUES(11,10,86,'Fantastic Vegan Options',4,'So many delicious vegan options!  Everything was flavorful and creative.');
INSERT INTO Review VALUES(12,14,40,'Noisy and Crowded',3,'Really noisy and crowded, making it hard to have a conversation.');
INSERT INTO Review VALUES(13,18,11,'Best Tacos in Town!',5,'Seriously the best tacos I’m town. Fresh ingredients and amazing flavor.');
INSERT INTO Review VALUES(14,6,28,'Uninspired Menu',2,'The menu felt very uninspired and limited.  Didn''t see anything I wanted.');
INSERT INTO Review VALUES(15,5,47,'Cozy Atmosphere',4,'Cozy and inviting atmosphere.  Perfect for a relaxed meal.');
INSERT INTO Review VALUES(16,3,31,'Slow Food',1,'Extremely slow food. Took forever to get our meals.');
INSERT INTO Review VALUES(17,1,23,'Delicious Pastries',3,'The pastries were amazing, but the rest of the meal was just okay.');
INSERT INTO Review VALUES(18,2,8,'Overcooked Steak',2,'The steak was overcooked and dry. Very disappointing.');
INSERT INTO Review VALUES(19,16,98,'Good Value',4,'Good quality food at a reasonable price. A great value!');
INSERT INTO Review VALUES(20,18,67,'Small Portions',3,'The portions were quite small for the price.');
INSERT INTO Review VALUES(21,10,11,'Friendly Staff',5,'The staff were incredibly friendly and attentive.');
INSERT INTO Review VALUES(22,2,75,'Average Italian',3,'Average Italian food. Nothing to write home about.');
INSERT INTO Review VALUES(23,16,37,'Excellent Wine List',4,'Impressive wine list with a wide selection.');
INSERT INTO Review VALUES(24,10,73,'Dirty Tables',1,'The tables were dirty and sticky. Very unappealing.');
INSERT INTO Review VALUES(25,7,87,'Fresh Seafood',5,'The seafood was incredibly fresh and flavorful.');
INSERT INTO Review VALUES(26,16,91,'Rude Manager',2,'The manager was rude and unhelpful when we brought up a concern.');
INSERT INTO Review VALUES(27,9,32,'Perfect Coffee',4,'The coffee was perfectly brewed and delicious.');
INSERT INTO Review VALUES(28,17,27,'Limited Vegetarian Options',3,'They had very few vegetarian options.');
INSERT INTO Review VALUES(29,11,18,'Live Music',5,'Great live music and a lively atmosphere!');
INSERT INTO Review VALUES(30,11,32,'Too Salty',2,'Everything was way too salty.');
INSERT INTO Review VALUES(31,16,49,'Wonderful Dessert',4,'The desserts were absolutely wonderful!');
INSERT INTO Review VALUES(32,17,40,'Unorganized',1,'The restaurant was very unorganized.');
INSERT INTO Review VALUES(33,12,74,'Authentic Cuisine',5,'Authentic cuisine that transported me to another country.');
INSERT INTO Review VALUES(34,2,16,'Mediocre Experience',3,'A mediocre experience overall, nothing stood out.');
INSERT INTO Review VALUES(35,6,55,'Clean Restaurant',4,'A very clean and well-maintained restaurant.');
INSERT INTO Review VALUES(36,6,85,'Slow Service',2,'Extremely slow service, we waited forever.');
INSERT INTO Review VALUES(37,14,66,'Delicious Cocktails',5,'The cocktails were expertly crafted and delicious!');
INSERT INTO Review VALUES(38,17,7,'Bland Food',2,'The food was incredibly bland and lacked flavor.');
INSERT INTO Review VALUES(39,14,62,'Friendly Environment',4,'A very friendly and welcoming environment.');
INSERT INTO Review VALUES(40,3,7,'Overpriced',1,'Way overpriced for what you get.');
INSERT INTO Review VALUES(41,8,59,'Great Atmosphere',5,'A fantastic atmosphere – perfect for a night out.');
INSERT INTO Review VALUES(42,18,62,'Small Space',3,'The space is quite small and cramped.');
INSERT INTO Review VALUES(43,13,59,'Amazing Selection',4,'They have a truly amazing selection of dishes.');
INSERT INTO Review VALUES(44,8,11,'Unsatisfactory Meal',2,'Overall, a very unsatisfactory meal.');
INSERT INTO Review VALUES(45,1,48,'Excellent Presentation',5,'The presentation of the food was excellent.');
INSERT INTO Review VALUES(46,3,52,'Not Worth the Hype',3,'It’s not as good as the hype suggests.');
INSERT INTO Review VALUES(47,8,1,'Delicious Bread',4,'The bread was exceptional – warm and crusty.');
INSERT INTO Review VALUES(48,5,22,'Loud Music',2,'The music was far too loud.');
INSERT INTO Review VALUES(49,8,78,'Wonderful View',5,'The view from the restaurant was breathtaking.');
INSERT INTO Review VALUES(50,13,23,'Hard to Find',1,'The restaurant was difficult to find.');
INSERT INTO Review VALUES(51,17,105,'bad',1,'');
INSERT INTO Review VALUES(52,17,108,'very bad',1,'portion sizes are just too low!');
